  US: "NYC",
  FR: "PAR",
  DE: "BER",
  RU: "MOW",
  UA: "KBP",
  IT: "ROM",
  ES: "MAD",
  NL: "AMS",
  PL: "WAW",
  JP: "TYO",
  CA: "YTO",
  AU: "SYD",
  IL: "TLV",
};

