    removeEventListener("pointermove", move);
    removeEventListener("pointerup", up);
    suppressClick();
    if (!moved) {
      const again = $("schedule").querySelector(`.sch-keep[data-keep="${at}"]`);
      if (again) openDayMenu(at, again);
    }
