    const menu = calMenu();
    const keep = e.target.closest("[data-keep]");
    const add = e.target.closest("[data-add]");
    const remove = e.target.closest("[data-own-remove]");
    if (!keep && !add && !remove) return;
    e.stopPropagation();
    if (keep) {
      setKept(menu.dataset.date, keep.dataset.keep);
    } else if (add) {
