[dir="rtl"] .sch-emoji {
  left: auto;
  right: -2px;
  transform: translate(50%, -50%);
}
[dir="rtl"] .lane-remove {
  right: auto;
  left: 4px;
}
[dir="rtl"] .win-handle--start .win-flag {
  transform: translateX(50%);
}
[dir="rtl"] .win-handle--end .win-flag {
  transform: translateX(-50%);
}

/* --- the version popup --------------------------------------------------- */

/* Each front-end ships its own rules for the shared popup module (a stylesheet
  padding: 0 8px;
  border-radius: 8px;
  font-size: 0.8rem;
}

/* --- the four blockers ----------------------------------------------------
 *
 * The day's two boundaries and the window's two ends, drawn on the calendar.
 * The lines, their grips and their flags are plan.css's own components
 * (.sch-dayline / .sch-zone / .sch-meal), so this is the overlay that holds
 * them, the date edges the Fringe planner has no equivalent of, and the
 * nights the window leaves out.
 */
.sch-blockers {
  position: absolute;
  inset-inline-end: 0;
  z-index: 6;
  pointer-events: none;
}
.sch-dayline:focus-visible,
.sch-dateedge:focus-visible {
  outline: none;
}
.sch-dayline:focus-visible .dl-flag,
.sch-dateedge:focus-visible .de-flag {
  background: var(--violet);
  color: #fff;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--violet) 40%, transparent);
}
/* A boundary further out than the axis reaches sits on the axis edge; its flag
   still carries the hour it really holds, so the two never disagree. */
.sch-dayline.is-beyond {
  border-top-style: dashed;
}
/* A start boundary drawn on the axis top has nothing above it to hang its flag
   in, so the flag drops below the line rather than over the day headers. */
.sch-dayline--start.is-beyond .dl-flag {
  bottom: auto;
  top: 6px;
}

/* Where the window starts and ends, across the columns rather than down the
   hours. Positioned inline-start in both directions (planNG.js measures
   the columns' own boxes), so only the flag's own centring is mirrored. */
.sch-dateedge {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 0;
  border-inline-start: 2px solid var(--violet);
  pointer-events: none;
  z-index: 7;
}
.sch-dateedge .de-grip {
  position: absolute;
  inset-inline-start: -8px;
  top: 0;
  width: 16px;
  height: 100%;
  cursor: ew-resize;
  pointer-events: auto;
  touch-action: none;
}
.sch-dateedge .de-grip::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 12px;
  height: 26px;
  border-radius: 7px;
  background-color: var(--violet);
  background-image: linear-gradient(#fff, #fff), linear-gradient(#fff, #fff);
  background-repeat: no-repeat;
  background-size: 1.5px 12px;
  background-position: 4px center, 7.5px center;
  box-shadow: 0 1px 4px rgba(16, 24, 40, 0.3);
  pointer-events: none;
}
.sch-dateedge .de-flag {
  position: absolute;
  top: 6px;
  inset-inline-start: 0;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 7px;
  border: 1px solid var(--violet);
  border-radius: 999px;
  background: var(--paper);
  color: var(--violet-dark);
  font-size: 0.6rem;
  font-weight: 700;
  line-height: 1.6;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
  pointer-events: none;
}
/* Each flag hangs INSIDE the window rather than astride its own edge: the
   calendar's scroller clips whatever leaves it, and the last night's edge is
   the scroller's own far side. */
.sch-dateedge--end .de-flag {
  inset-inline-start: auto;
  inset-inline-end: 2px;
}
.sch-dateedge .wf-cap {
  color: var(--muted);
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* A night the window leaves out: hatched like the hours outside the day, so
   both kinds of blocker shut a region out the same way. */
.sch-day--out {
  background: repeating-linear-gradient(
    -45deg,
    light-dark(rgba(16, 24, 40, 0.06), rgba(255, 255, 255, 0.05)) 0 6px,
    light-dark(rgba(16, 24, 40, 0.02), rgba(255, 255, 255, 0.015)) 6px 12px
  );
}
.sch-day--out .sch-day-head {
  opacity: 0.5;
}
.sch-day--out .sch-body {
  background-image: none;
}

/* The hatch plan.css draws over its zones and meal bands is tuned for a white
   board; in the dark it disappears into it. */
.sch-zone,
.sch-meal {
  background: repeating-linear-gradient(
    -45deg,
    light-dark(rgba(16, 24, 40, 0.05), rgba(255, 255, 255, 0.05)) 0 6px,
    light-dark(rgba(16, 24, 40, 0.02), rgba(255, 255, 255, 0.015)) 6px 12px
  );
}
/* A meal here is a statement, not a handle: it is moved from the question that
   asked for it, so nothing on the calendar takes the pointer. */
.sch-meal {
  cursor: default;
  pointer-events: none;
}

/* --- the year ------------------------------------------------------------ */

/* The strip across the top: twelve months, a bar per festival edition. Every
   position is logical, so a right-to-left page runs the year from the right. */
.timeline {
  margin: 14px 0 4px;
  padding: 10px 12px 8px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  box-shadow: var(--shadow-soft);
}
.tl-months {
  position: relative;
  height: 18px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 8px;
}
.tl-month {
  position: absolute;
  top: 0;
  padding-inline-start: 4px;
  border-inline-start: 1px solid var(--line);
  font-size: 0.72rem;
  line-height: 18px;
  color: var(--muted);
  white-space: nowrap;
}
.tl-month--first {
  border-inline-start: 0;
  padding-inline-start: 0;
}
.tl-track {
  position: relative;
  min-height: 36px;
  font-size: 0.6rem; line-height: 1; pointer-events: none;
}

/* --- the calendar's two floating surfaces --------------------------------- */
/* The card, not the calendar, is what they are positioned in — see placePop. */
.plan-result { position: relative; }
.cal-pop {
  position: absolute; z-index: 40; width: max-content; max-width: 300px;
  padding: 8px 10px; border-radius: 10px;
  background: var(--paper); border: 1px solid var(--line);
  box-shadow: 0 10px 26px rgba(16, 24, 40, 0.18);
  font-size: 0.7rem; line-height: 1.35; color: var(--ink);
}
.cal-pop .pop-title {
  margin: 0 0 2px; font-family: var(--display); font-weight: 700; font-size: 0.76rem;
}
.cal-pop .pop-lead { margin: 0 0 6px; color: var(--muted); font-size: 0.64rem; }
.cal-pop .pop-foot { margin: 6px 0 0; color: var(--muted); font-size: 0.62rem; }
.cal-pop .pop-more { margin: 4px 0 0; color: var(--muted); font-size: 0.66rem; }
.panel-more { margin: 6px 8px 2px; color: var(--muted); font-size: 0.72rem; line-height: 1.35; }
.pop-nights, .pop-rivals { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }

