"use strict";
const { jerusalemReady, jerusalemStarred, settle } = require("../../shared/case-helpers");

// A favourited show that plays three evenings, drafted onto Monday. Refusing
// that one evening moves it to another of its own — and it competes for the
// rest as a scarcer show than it was, which the popup's badge then says.
const MON = '.sch-day[data-date="2026-10-19"]';
const TUE = '.sch-day[data-date="2026-10-20"]';

module.exports = {
  description: "'not this night' moves the show to another of its own nights",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  localStorage: jerusalemStarred(["yolo"]),
  ready: jerusalemReady,
  async capture(page, t) {
    const pair = () => t.unionClip([MON, TUE], 4);
    const before = await pair();
    // The verdicts live in the popup, so the card has to be opened first.
    await page.hover(`${MON} .sch-show--fav`);
    await settle(page);
    await page.click('#calPreview [data-verdict="noTime"]');
    await settle(page);
    return t.animate([before, await pair()]);
  },
};
"use strict";
const { clickStackBand, jerusalemReady, settle } = require("../../shared/case-helpers");

// Monday at 22:00: a one-night show took the hour from a free late-night that
// plays four evenings. Taking that one from the stack is a lock, and a lock is
// placed before the draft runs — so it seats the show the scarcity rule would
// never have picked, and the hour stops offering anyone.
const NIGHT = '.sch-day[data-date="2026-10-19"]';

module.exports = {
  description: "locking a night holds it, even against a scarcer contender",
  page: "/planNG/?festival=jerusalem-comedy",
  viewport: "desktop",
  ready: jerusalemReady,
  async capture(page, t) {
    const slot = page.locator(`${NIGHT} .sch-slot:has(.sch-stack)`).first();
    const frame = async () => t.clip(t.pad(await slot.boundingBox(), 8));
    const before = await frame();

    await clickStackBand(page, slot);
    await page.click("#calRivals .pop-rival");
    await page.waitForSelector(`${NIGHT} .sch-show--locked`);
    await settle(page);

    const after = page.locator(`${NIGHT} .sch-slot:has(.sch-show--locked)`).first();
    return t.animate([before, await t.clip(t.pad(await after.boundingBox(), 8))]);
  },
};

